const body = $json.body || $json;
const headers = $json.headers || {};
const query = $json.query || {};

const expectedToken = $env.REMBRO_N8N_WEBHOOK_TOKEN || '';
if (expectedToken && query.token !== expectedToken) {
  return [{ json: { shouldRun: false, reason: 'Invalid webhook token' } }];
}

const event = headers['x-github-event'] || headers['X-GitHub-Event'] || body.event || 'unknown';
const ref = body.ref || '';
const after = body.after || '';
const repository = body.repository?.full_name || 'unknown';
const pusher = body.pusher?.name || body.sender?.login || 'unknown';

return [{
  json: {
    shouldRun: event === 'push' && ref === 'refs/heads/main',
    event,
    ref,
    after,
    repository,
    pusher,
    baseUrl: $env.REMBRO_BASE_URL || 'http://194.31.150.130:3001',
    timeoutSeconds: Number($env.REMBRO_SMOKE_TIMEOUT_SECONDS || 300),
    intervalSeconds: Number($env.REMBRO_SMOKE_INTERVAL_SECONDS || 10)
  }
}];

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const baseUrl = $json.baseUrl.replace(/\/$/, '');
const timeoutMs = Math.max(30, $json.timeoutSeconds) * 1000;
const intervalMs = Math.max(2, $json.intervalSeconds) * 1000;
const startedAt = Date.now();
const checks = [
  { name: 'frontend', url: `${baseUrl}/`, expectText: 'Rembro' },
  { name: 'health', url: `${baseUrl}/api/health`, expectText: 'ok' },
  { name: 'products', url: `${baseUrl}/api/products`, expectText: 'Urban Rugzak' },
  { name: 'swagger', url: `${baseUrl}/api-docs`, expectText: 'swagger-ui' }
];

async function runChecks() {
  const results = [];
  for (const check of checks) {
    const response = await fetch(check.url, { headers: { 'User-Agent': 'n8n-rembro-smoketest' } });
    const text = await response.text();
    const ok = response.ok && text.includes(check.expectText);
    results.push({ name: check.name, url: check.url, status: response.status, ok });
    if (!ok) return { ok: false, results };
  }
  return { ok: true, results };
}

let attempt = 0;
let lastResult = null;
while (Date.now() - startedAt <= timeoutMs) {
  attempt += 1;
  try {
    lastResult = await runChecks();
    if (lastResult.ok) {
      return [{
        json: {
          status: 'verified',
          attempts: attempt,
          durationSeconds: Math.round((Date.now() - startedAt) / 1000),
          repository: $json.repository,
          commit: $json.after,
          pusher: $json.pusher,
          baseUrl,
          checks: lastResult.results
        }
      }];
    }
  } catch (error) {
    lastResult = { ok: false, error: error.message };
  }
  await sleep(intervalMs);
}

throw new Error(`Rembro smoke test failed after ${attempt} attempts: ${JSON.stringify(lastResult)}`);
